<?php require_once __DIR__.'/../config/auth.php';$q=trim($_GET['q']??'');$cat=$_GET['categoria']??'';$sql='SELECT * FROM livros WHERE 1';$p=[];if($q){$sql.=' AND (titulo LIKE ? OR autor LIKE ? OR isbn LIKE ? OR codigo_barras LIKE ?)';$p=array_fill(0,4,'%'.$q.'%');}if($cat){$sql.=' AND categoria=?';$p[]=$cat;}$sql.=' ORDER BY titulo';$s=db()->prepare($sql);$s->execute($p);$books=$s->fetchAll();$categories=db()->query('SELECT DISTINCT categoria FROM livros WHERE categoria<>"" ORDER BY categoria')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Catálogo de livros';require __DIR__.'/../includes/header.php';if(user())require __DIR__.'/../includes/dashboard-nav.php';else require __DIR__.'/../includes/public-nav.php';?><div class="<?=user()?'':'section'?>"><p class="subtext">Pesquise por título, autor, código ou ISBN.</p><form class="filterbar" method="get"><div class="searchbar"><input type="search" data-catalog-search name="q" value="<?=e($q)?>" placeholder="Pesquise no acervo..." autocomplete="off" inputmode="search"></div><select name="categoria"><option value="">Todas as categorias</option><?php foreach($categories as $c):?><option <?=$cat===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="btn btn-small">Filtrar</button></form><div class="book-grid"><?php foreach($books as $l):?><article class="book-card"><?php if($l['capa']):?><img class="cover" src="<?=base_url('assets/uploads/capas/'.$l['capa'])?>" alt="Capa de <?=e($l['titulo'])?>"><?php else:?><div class="cover cover-placeholder"><?=e($l['titulo'])?></div><?php endif;?><div class="book-info"><h3><?=e($l['titulo'])?></h3><p><?=e($l['autor'])?><br><?=e($l['categoria'])?> · <?=e($l['ano_publicacao'])?></p><span class="badge <?=$l['quantidade_disponivel']?'':'off'?>"><?=$l['quantidade_disponivel']?'Disponível':'Indisponível'?></span><a class="btn btn-small" style="float:right" href="<?=base_url('aluno/livro.php?id='.(int)$l['id'])?>">Detalhes</a></div></article><?php endforeach;?><?php if(!$books):?><div class="empty">Nenhum livro encontrado para sua busca.</div><?php endif;?></div></div><?php if(user())require __DIR__.'/../includes/dashboard-footer.php';else require __DIR__.'/../includes/footer.php';?>
